<script>
import Swiper, { Navigation, Pagination } from 'swiper'
import 'swiper/swiper-bundle.css'
Swiper.use([ Navigation, Pagination ])

import source from '@/assets/questionsSource.json';

export default {
  name: 'Quiz',
  data () {
    return {
      current: -1,
      responses: [],
      questionsSource: source.questions,
      modes: source.modes,
      currentModeId: source.modes[0].id,
      swiper: null
    }
  },
  computed: {
    currentMode: function () {
      return this.modes.find((mode) => {
        return mode.id === this.currentModeId
      })
    },
    resultSum: function () {
      return this.responses.reduce((sum, item, index) => {
        return sum += (this.questions[index].min * item) + (this.questions[index].max * (1 - item))
      }, 0)
    },
    resultTitle: function () {
      return this.currentMode.results.find((variant) => {
        if (variant.to && variant.from) {
          return variant.from <= this.resultSum && this.resultSum <= variant.to
        } else if (variant.to && !variant.from) {
          return this.resultSum < variant.to
        } else if (!variant.to && variant.from) {
          return variant.from < this.resultSum
        } else {
          return false
        }
      }).title
    },
    result: function () {
      return {
        sum: this.resultSum.toFixed(3),
        title: this.resultTitle,
      }
    },
    questions: function () {
      return this.questionsSource.filter((question) => {
        return this.currentMode.questions.includes(question.id)
      })
    }
  },
  methods: {
    changeMode: function (event) {
      this.currentModeId = Number(event.target.value)
      this.responses.length = this.currentMode.questions.length

      if (this.current > this.currentMode.questions.length) {
        this.current = this.responses.length
      }
    },
    start: function () {
      this.current = 0
    },
    confirm: function (response) {
      this.responses[this.current] = response
      this.current++
    },
    reset: function () {
      this.current = -1
      this.responses.length = 0
    },
    copy: function () {
      const table = document.querySelector('.app__copy-table > table')
      const tableHTML = table.outerHTML
      const blobHTML = new Blob([tableHTML], {
        type: 'text/html'
      })

      const clipboardItem = new ClipboardItem({
        'text/html': blobHTML
      })

      navigator.clipboard.write([clipboardItem]).then(() => {
        alert('Таблица скопирована! Для того чтобы вставить, откройте документ и нажмите Ctrl+V')
      }, (err) => {
        alert('Простите, не удалось скопировать. Вы можете сделать скриншот таблицы и вставить её как картинку')
      });
    },
  },
  watch: {
    current: function () {
      setTimeout(()=>{
        if (this.$el.querySelector('.swiper-container') && this.questions[this.current].gallery && this.questions[this.current].gallery.length > 1) {
          if (this.swiper) {
            this.swiper.destroy()
          }

          this.swiper = new Swiper(this.$el.querySelector('.swiper-container'), {
            slidesPerView: 1,
            spaceBetween: 20,
            pagination: {
              el: '.swiper-pagination',
              clickable: true
            },
            navigation: {
              nextEl: '.swiper-button-next',
              prevEl: '.swiper-button-prev',
            }
          })
        }
      })
    }
  }
}
</script>

